-- CampusO: AYBU İşletme Fakültesi gerçek ders programı verisi
-- Kaynak: kullanıcının paylaştığı AYBÜ İşletme Fakültesi 2025-2026 güz/bahar
-- ders programı görselleri (İşletme, Finans ve Bankacılık, Uluslararası Ticaret
-- ve İşletmecilik, Yönetim Bilişim Sistemleri bölümleri). Ortak 1-2. sınıf
-- çekirdek dersleri (BUS1xx/2xx, ENG1xx/2xx, TDL1xx, TİT1xx) dört bölüme de
-- eklenmiştir; bölüme özgü dersler yalnız ilgili bölüme eklenmiştir.
-- Not: gerçek görsellerde yer almayan (bu dönem programında görünmeyen)
-- seçmeli dersler bilinçli olarak eklenmedi — uydurma veri girilmedi.
-- Not 2: baslangic_saat/bitis_saat BİLEREK girilmedi — ders saatleri dönemden
-- döneme (2026-27 güz/bahar vb.) değişebildiği için sabit saat yazılmadı.
-- Bu yüzden önce bu iki alan zorunlu olmaktan çıkarılıyor, sonra veri ekleniyor;
-- kesin saat belli olunca admin panelinden ayrıca girilebilir.

begin;

alter table public.ders_programi
  alter column baslangic_saat drop not null,
  alter column bitis_saat drop not null;

delete from public.ders_programi
where bolum in ('İşletme', 'Finans ve Bankacılık', 'Uluslararası Ticaret ve İşletmecilik', 'Yönetim Bilişim Sistemleri');


commit;
